% SYMMETRIC DIFFERENTIATORS: two delayed branches, then weighted subtraction
% (paper Eq. (2) on each branch, Eq. (8) on the two results)
%
% Block 0 (adapter), unchanged:  EV signal --> ... --> UMP = m_in
%
% Each differentiator has two branches of the same form:
%   fast branch   x --r_F--> m_F --r_Fr--> fast rail      delay tau_F = 1/k_Fr
%   slow branch   x --r_S--> m_S --r_Sr--> slow rail      delay tau_S = 1/k_Sr
%   canceler      fast rail + slow rail --r_I--> products
%   each rail is also removed with the same rate constant k_r.
% m_F and m_S are the delay pools of Eq. (2); the canceler never touches them.
% Because both rails lose the same k_r and r_I takes one molecule of each,
%   fast rail - slow rail = w * ( x delayed by tau_F  -  x delayed by tau_S ),
% smoothed with 1/k_r, whatever the strength of r_I. For a slow input this
% is  w*(tau_S - tau_F)*dx/dt :  Delta_t = tau_S - tau_F, as in the paper.
% With a strong r_I only one rail survives: the fast rail while x rises,
% the slow rail while x falls. At rest both are near zero.
%
% Differentiator 1:  x = m_in.  Rails m_P1 (fast) and m_d1 (slow).
%   OUTPUT = m_d1: it rises while m_in FALLS (inverted polarity).
%   Removal of m_d1: the load, r_F_2 and r_S_2 of differentiator 2 consume it.
%   Removal of m_P1: r_Fx (NEW, not in the workbook).
% Differentiator 2:  x = m_d1.  Rails m_d2 (fast) and m_N2 (slow).
%   OUTPUT = m_d2: it rises while m_d1 rises.
%   Removal of m_d2: r_Fx_2 (NEW).   Removal of m_N2: r_Sx_2 (NEW).
% The three new removals use the constants of r_Fr / r_Fr_2.
% Counter, as before: r_c and r_I2 are activated by m_d2 (not consumed).
%
% Kinetics: every differentiator reaction is first order, rate = k*m with
% k = kcat*[E]/K_M; r_I is second order, k_I = kcat*[E]/(K_M*K_M). Block 0
% and the counter keep Michaelis-Menten rates. Only the analysed distance
% (row) is simulated, from the rest state.
%
% Needs Parameters.m, Dataset_cell2cell.mat and kinetics_BRENDA.xlsx.
clc;
% clearvars;
close all;

addingPathParentFolderByName('code'); %[output:4d149871]
Parameters                               % provides dt0 and fontsize
%%
%[text] ## 1. Input data
% load Dataset_cell2cell.mat
Dataset  = rmmissing(Dataset);
dist     = table2array(Dataset(:,1));
vesicles = table2array(Dataset(:,2:end));

row = 1;                                 % distance analysed in detail
N = size(vesicles,2);
t = (0:N-1)'*dt0;
assert(N >= 3 && all(isfinite(vesicles(row,:))) && all(vesicles(row,:) >= 0) && vesicles(row,1) > 0, ...
    'Use a finite nonnegative EV signal with a positive first sample.');
%%
%[text] ## 2. Enzyme constants from the BRENDA workbook
%Uncomment below for reading the constants from https://www.brenda-enzymes.info/functional_parameter_statistics.php 

% %Loggin in Brenda for quering the enzyme parameters https://www.brenda-enzymes.info/functional_parameter_statistics.php 
% % Default values
% credentialsFile = fullfile(pwd,'BRENDA_credentials.txt');
% if isfile(credentialsFile)
%     fid = fopen(credentialsFile,'rt','n','UTF-8');
%     assert(fid ~= -1, 'Cannot open credentials file.');
% 
%     emailFromFile    = fgetl(fid);
%     passwordFromFile = fgetl(fid);
%     fclose(fid);
% 
%     assert(ischar(emailFromFile) && ischar(passwordFromFile), ...
%         'Credentials file must contain two lines.');
%     assert(~isempty(strtrim(emailFromFile)) && ~isempty(passwordFromFile), ...
%         'Email and password must not be empty.');
% 
%     email    = strtrim(emailFromFile);
%     password = passwordFromFile; % Preserve password spaces.
% 
%     clear fid emailFromFile passwordFromFile
% end
% 
% 
% brendaKineticsTable('Block_7_Selected_Motifs.txt', 'kinetics_BRENDA.xlsx', email, password);

% Sheet "values" of kinetics_BRENDA.xlsx: reaction label in column B, and the
% columns K_M [mM], SA [umol/min/mg] and MW [mg/umol] found by their titles.
% kcat [1/s] = SA*MW/60.
raw = readcell('kinetics_BRENDA.xlsx','Sheet','values');
isText = @(x) ischar(x) || (isstring(x) && isscalar(x) && ~ismissing(x));
hdrRow = find(any(cellfun(@(x) isText(x) && startsWith(string(x),"K_M"),raw),2),1);
assert(~isempty(hdrRow),'Header row (a cell starting with "K_M") not found in the workbook.');
colOf = @(title) find(cellfun(@(x) isText(x) && startsWith(string(x),title),raw(hdrRow,:)),1);
colKM = colOf("K_M");  colSA = colOf("SA");  colMW = colOf("MW");

%Reading the first differentiator enzyme-constants
reactionNames = {'r_S','r_Sr','r_F','r_Fr','r_I'};

KM = nan(1,5);  kcat = nan(1,5);
for i = 1:5
    r = find(cellfun(@(x) isText(x) && strcmp(strtrim(char(x)),reactionNames{i}),raw(:,2)),1);
    assert(~isempty(r),'Reaction %s not found in column B of the workbook.',reactionNames{i});
    KM(i)   = raw{r,colKM};
    kcat(i) = raw{r,colSA}*raw{r,colMW}/60;
end
assert(all(isfinite([KM kcat])) && all([KM kcat] > 0),'K_M, SA and MW of the five reactions must be positive numbers.');

KM_S  = KM(1);  kcat_S  = kcat(1);       % r_S :  m_in -> m_S
KM_Sr = KM(2);  kcat_Sr = kcat(2);       % r_Sr:  m_S  -> m_d1  (slow rail)
KM_F  = KM(3);  kcat_F  = kcat(3);       % r_F :  m_in -> m_F
KM_Fr = KM(4);  kcat_Fr = kcat(4);       % r_Fr:  m_F  -> m_P1  (fast rail)
KM_I  = KM(5);  kcat_I  = kcat(5);       % r_I :  m_P1 + m_d1 -> products (K_M used for both substrates: assumed)

%Reading the second differentiator enzyme-constants
reactionNames2 = {'r_S_2','r_Sr_2','r_F_2','r_Fr_2','r_I_2'};
KM2 = nan(1,5);  kcat2 = nan(1,5);
for i = 1:5
    r = find(cellfun(@(x) isText(x) && strcmp(strtrim(char(x)),reactionNames2{i}),raw(:,2)),1);
    assert(~isempty(r),'Reaction %s not found in column B of the workbook.',reactionNames2{i});
    KM2(i)   = raw{r,colKM};
    kcat2(i) = raw{r,colSA}*raw{r,colMW}/60;
end
KM_S_2  = KM2(1);  kcat_S_2  = kcat2(1);   % r_S_2 : m_d1 -> m_S2
KM_Sr_2 = KM2(2);  kcat_Sr_2 = kcat2(2);   % r_Sr_2: m_S2 -> m_N2 (slow rail)
KM_F_2  = KM2(3);  kcat_F_2  = kcat2(3);   % r_F_2 : m_d1 -> m_F2
KM_Fr_2 = KM2(4);  kcat_Fr_2 = kcat2(4);   % r_Fr_2: m_F2 -> m_d2 (fast rail)
KM_I_2  = KM2(5);  kcat_I_2  = kcat2(5);   % r_I_2 : m_d2 + m_N2 -> products (K_M for both: assumed)

%Reading the counter enzyme-constants
reactionNamesC = {'r_Cp','r_Cg','r_Cr'};
KMC = nan(1,3);  kcatC = nan(1,3);
for i = 1:3
    r = find(cellfun(@(x) isText(x) && strcmp(strtrim(char(x)),reactionNamesC{i}),raw(:,2)),1);
    assert(~isempty(r),'Reaction %s not found in column B of the workbook.',reactionNamesC{i});
    KMC(i)   = raw{r,colKM};
    kcatC(i) = raw{r,colSA}*raw{r,colMW}/60;
end
assert(all(isfinite([KM2 kcat2 KMC kcatC])) && all([KM2 kcat2 KMC kcatC] > 0),'K_M, SA and MW must be positive numbers.');
KM_Cp   = KMC(1);  kcat_Cp = kcatC(1);   % r_c  = r_Cp: buffered substrate -> m_c, activated by m_d2
KM_Cg_c = KMC(2);  kcat_Cg = kcatC(2);   % r_I1 = r_Cg: m_c + m_I -> products;   K_M for m_c
KM_Cg_I = KMC(2);                        %               K_M for m_I: assumed equal
KM_Cr   = KMC(3);  kcat_Cr = kcatC(3);   % r_I2 = r_Cr: m_I -> products, activated by m_d2
%%
%[text] ## 3. Design choices
E_max = 0.02;                            % largest feasible enzyme concentration [mM] (20 uM)
m_in_target = 0.00125;                   % resting input level [mM]

% Differentiator 1
tau_F1 = 30;                             % delay of the fast branch (pool m_F) [s]
tau_S1 = 60;                             % delay of the slow branch (pool m_S) [s];  Delta_t = tau_S1 - tau_F1
tau_r1 = 30;                             % common removal time of the two rails m_P1 and m_d1 [s]
w_1    = 1;                              % gain: m_P1 - m_d1 = w_1*(fast-delayed m_in - slow-delayed m_in)
% Differentiator 2
tau_F2 = 30;                             % delay of the fast branch (pool m_F2) [s]
tau_S2 = 60;                             % delay of the slow branch (pool m_S2) [s]
tau_r2 = 30;                             % common removal time of the two rails m_d2 and m_N2 [s]
%                                          (its gain is fixed by the load: w_2 = tau_r2/(2*tau_r1))
% Canceler r_I and r_I_2
ideal_canceler = true;                   % true : strong enough to leave the rails at rest_1, rest_2
%                                          false: limited to E_max, to see what is feasible
rest_1 = 1e-7;                           % wanted resting level of the rails of D1 [mM] (ideal canceler)
rest_2 = 1e-8;                           % wanted resting level of the rails of D2 [mM] (ideal canceler)
% Counter
gate_factor   = 100;                     % K_gate = gate_factor * resting m_d2
count_step    = 0.01;                    % m_c gained if r_c ran fully activated for pulse_time [mM]
pulse_time    = 200;                     % nominal length of an m_d2 pulse [s]
tau_reset     = 600;                     % reset time constant of m_c [s]
m_I_base      = 2;                       % buffered level of m_I [mM] (illustrative)
tau_I_supply  = 60;                      % refill time of m_I [s]
assert(tau_S1 > tau_F1 && tau_S2 > tau_F2,'The slow branch must have the larger delay.');
%%
%[text] ## 4. Rate constants, rest state and enzyme concentrations
% ---- Differentiator 1 ----
k_r1 = 1/tau_r1;                         % removal of each rail
k_F  = w_1*k_r1;                         % m_in -> m_F
k_S  = k_F;                              % m_in -> m_S: the same flux into both branches
k_Fr = 1/tau_F1;                         % m_F -> m_P1
k_Sr = 1/tau_S1;                         % m_S -> m_d1
k_Fx = k_r1;                             % m_P1 -> products (new reaction)
k_F_2 = k_r1/2;  k_S_2 = k_r1/2;         % m_d1 -> m_F2 and m_d1 -> m_S2: together the k_r of m_d1
flux_1 = k_F*m_in_target;                % resting flux through each branch [mM/s]
m_F_ref = k_F*m_in_target/k_Fr;
m_S_ref = k_S*m_in_target/k_Sr;
if ideal_canceler
    assert(k_r1*rest_1 < flux_1,'rest_1 is too high: lower it.');
    k_I = (flux_1-k_r1*rest_1)/rest_1^2;
else
    k_I = kcat_I*E_max/(KM_I*KM_I);
end
p1_ref = (-k_r1+sqrt(k_r1^2+4*k_I*flux_1))/(2*k_I);      % resting m_P1 = resting m_d1

% ---- Differentiator 2 (input: m_d1) ----
k_r2   = 1/tau_r2;
k_Fr_2 = 1/tau_F2;                       % m_F2 -> m_d2
k_Sr_2 = 1/tau_S2;                       % m_S2 -> m_N2
k_Fx_2 = k_r2;   k_Sx_2 = k_r2;          % removal of m_d2 and of m_N2 (new reactions)
flux_2 = k_F_2*p1_ref;                   % resting flux through each branch of D2
m_F2_ref = k_F_2*p1_ref/k_Fr_2;
m_S2_ref = k_S_2*p1_ref/k_Sr_2;
if ideal_canceler
    assert(k_r2*rest_2 < flux_2,'rest_2 is too high for the resting m_d1: lower it.');
    k_I_2 = (flux_2-k_r2*rest_2)/rest_2^2;
else
    k_I_2 = kcat_I_2*E_max/(KM_I_2*KM_I_2);
end
p2_ref = (-k_r2+sqrt(k_r2^2+4*k_I_2*flux_2))/(2*k_I_2);  % resting m_d2 = resting m_N2

% ---- Enzyme concentrations, from k = kcat*[E]/K_M ----
names_all = {'r_F';'r_Fr';'r_S';'r_Sr';'r_I';'r_Fx (new)'; ...
             'r_F_2';'r_Fr_2';'r_S_2';'r_Sr_2';'r_I_2';'r_Fx_2 (new)';'r_Sx_2 (new)'};
k_all = [k_F;k_Fr;k_S;k_Sr;k_I;k_Fx;k_F_2;k_Fr_2;k_S_2;k_Sr_2;k_I_2;k_Fx_2;k_Sx_2];
E_all = [k_F*KM_F/kcat_F; k_Fr*KM_Fr/kcat_Fr; k_S*KM_S/kcat_S; k_Sr*KM_Sr/kcat_Sr; k_I*KM_I^2/kcat_I; ...
         k_Fx*KM_Fr/kcat_Fr; ...
         k_F_2*KM_F_2/kcat_F_2; k_Fr_2*KM_Fr_2/kcat_Fr_2; k_S_2*KM_S_2/kcat_S_2; k_Sr_2*KM_Sr_2/kcat_Sr_2; ...
         k_I_2*KM_I_2^2/kcat_I_2; k_Fx_2*KM_Fr_2/kcat_Fr_2; k_Sx_2*KM_Fr_2/kcat_Fr_2];
reaction_parameters = table(names_all,k_all,1e3*E_all, ...
    'VariableNames',{'Reaction','k_per_s_or_per_mM_s','Enzyme_uM'});
disp(reaction_parameters); %[output:9f8a9687]
for i = find(E_all > E_max).' %[output:group:3caa73ea]
    warning('%s needs %.3g uM, above the limit of %.3g uM.',names_all{i},1e3*E_all(i),1e3*E_max); %[output:473bc69b] %[output:66771f97]
end %[output:group:3caa73ea]
fprintf('Rest: m_F %.3g, m_S %.3g, rails of D1 %.3g, m_F2 %.3g, m_S2 %.3g, rails of D2 %.3g mM\n', ... %[output:group:24a212b4] %[output:89f52d5f]
    m_F_ref,m_S_ref,p1_ref,m_F2_ref,m_S2_ref,p2_ref); %[output:group:24a212b4] %[output:89f52d5f]

% ---- Counter ----
K_gate = gate_factor*p2_ref;
k_I_supply = 1/tau_I_supply;
g_ref = p2_ref/(K_gate+p2_ref);
E_Cp = (count_step/pulse_time)/kcat_Cp;                  V_Cp = kcat_Cp*E_Cp;
E_Cr = min(E_max,k_I_supply*0.5*m_I_base/(kcat_Cr*0.5*m_I_base/(KM_Cr+0.5*m_I_base)));   V_Cr = kcat_Cr*E_Cr;
I_balance = @(x) k_I_supply*(m_I_base-x)-V_Cr*g_ref*x/(KM_Cr+x)-V_Cp*g_ref;
m_I_ref = fzero(I_balance,[0 m_I_base]);
E_Cg = KM_Cg_c/(tau_reset*kcat_Cg*(m_I_ref/(KM_Cg_I+m_I_ref)));   V_Cg = kcat_Cg*E_Cg;
m_c_ref = KM_Cg_c*V_Cp*g_ref/(V_Cg*m_I_ref/(KM_Cg_I+m_I_ref)-V_Cp*g_ref);
fprintf('Counter: K_gate %.3g mM; enzymes r_c %.3g, r_I1 %.3g, r_I2 %.3g uM\n',K_gate,1e3*E_Cp,1e3*E_Cg,1e3*E_Cr); %[output:6586075c]

% Block 0 supplies what r_S and r_F withdraw from m_in.
j_S_ref = k_S*m_in_target;  j_F_ref = k_F*m_in_target;
%%
%[text] ## 5. Block 0: design concentrations, buffered cosubstrates and capacities
%[text] Concentration targets \[mM\] and turnover numbers are illustrative, not measurements.
tau_B0   = 30;                                   % response time of each Block 0 pool [s]
pool_ref = (j_S_ref+j_F_ref)*tau_B0/1.1;         % reference concentration that gives tau_B0
cAMP_ref = pool_ref; AMP_ref = pool_ref; adn_ref = pool_ref; r1p_ref = pool_ref; uri_ref = pool_ref;
K_EV_AC = 10*vesicles(row,1);            % activation constant in DATASET EV units, not mM
m_ATP_B0 = 2; m_Pi_B0 = 1; m_uracil_B0 = 0.05; m_dUTP_B0 = 0.05;
Km_ADNCYC_ATP = 0.2;
Km_PDE1_cAMP = 10*cAMP_ref;
Km_NTD7_AMP = 10*AMP_ref;
Km_PUNP1_adn = 10*adn_ref;    Km_PUNP1_Pi = 0.1;
Km_PYNP2r_r1p = 10*r1p_ref;   Km_PYNP2r_uracil = 0.005;
Km_r1156_uri = 10*uri_ref;    Km_r1156_dUTP = 0.005;
kcat_ADNCYC = 100; kcat_PDE1 = 100; kcat_NTD7 = 100;
kcat_PUNP1 = 100; kcat_PYNP2r = 100; kcat_r1156 = 100;

% Buffered cosubstrates enter as constant saturation fractions.
ATP_fraction    = m_ATP_B0/(Km_ADNCYC_ATP+m_ATP_B0);
Pi_fraction     = m_Pi_B0/(Km_PUNP1_Pi+m_Pi_B0);
uracil_fraction = m_uracil_B0/(Km_PYNP2r_uracil+m_uracil_B0);
dUTP_fraction   = m_dUTP_B0/(Km_r1156_dUTP+m_dUTP_B0);

% The supply of UMP equals what r_S and r_F withdraw at m_in_target.
J_B0_ref = j_S_ref+j_F_ref;
EV_activity_ref = vesicles(row,1)/(K_EV_AC+vesicles(row,1));
V_ADNCYC = J_B0_ref/(EV_activity_ref*ATP_fraction);
V_PDE1   = J_B0_ref/(cAMP_ref/(Km_PDE1_cAMP+cAMP_ref));
V_NTD7   = J_B0_ref/(AMP_ref/(Km_NTD7_AMP+AMP_ref));
V_PUNP1  = J_B0_ref/((adn_ref/(Km_PUNP1_adn+adn_ref))*Pi_fraction);
V_PYNP2r = J_B0_ref/((r1p_ref/(Km_PYNP2r_r1p+r1p_ref))*uracil_fraction);
V_r1156  = J_B0_ref/((uri_ref/(Km_r1156_uri+uri_ref))*dUTP_fraction);

block0_parameters = table( ...
    {'ADNCYC (assumed EV control)';'PDE1';'NTD7';'PUNP1';'PYNP2r (reverse)';'r1156'}, ...
    [Km_ADNCYC_ATP;Km_PDE1_cAMP;Km_NTD7_AMP;Km_PUNP1_adn;Km_PYNP2r_r1p;Km_r1156_uri], ...
    [kcat_ADNCYC;kcat_PDE1;kcat_NTD7;kcat_PUNP1;kcat_PYNP2r;kcat_r1156], ...
    1e3*[V_ADNCYC/kcat_ADNCYC;V_PDE1/kcat_PDE1;V_NTD7/kcat_NTD7; ...
         V_PUNP1/kcat_PUNP1;V_PYNP2r/kcat_PYNP2r;V_r1156/kcat_r1156], ...
    [V_ADNCYC;V_PDE1;V_NTD7;V_PUNP1;V_PYNP2r;V_r1156], ...
    'VariableNames',{'Reaction','Km_mM','kcat_per_s','Enzyme_uM','Vmax_mM_per_s'});
disp(block0_parameters); %[output:559c0841]
%%
%[text] ## 6. Simulation (analysed distance) from the rest state
% Each step: (1) production and first-order removal with explicit Euler,
% giving trial values P and Q of the two rails; (2) the canceler applied
% implicitly. With D = P - Q (which the canceler does not change), the new
% P solves   P_new = P - dt*k*P_new*(P_new - D),   a quadratic with one
% positive root; then Q_new = P_new - D. Stable for any canceler strength.
EV = vesicles(row,:).';
m_cAMP = cAMP_ref*ones(N,1); m_AMP = AMP_ref*ones(N,1); m_adn = adn_ref*ones(N,1);
m_r1p = r1p_ref*ones(N,1);   m_uri = uri_ref*ones(N,1); m_in = m_in_target*ones(N,1);
m_F  = m_F_ref*ones(N,1);    m_S  = m_S_ref*ones(N,1);  m_P1 = p1_ref*ones(N,1);  m_d1 = p1_ref*ones(N,1);
m_F2 = m_F2_ref*ones(N,1);   m_S2 = m_S2_ref*ones(N,1); m_d2 = p2_ref*ones(N,1);  m_N2 = p2_ref*ones(N,1);
m_c = m_c_ref*ones(N,1);     m_I = m_I_ref*ones(N,1);   gate = g_ref*ones(N,1);

for n = 1:N-1
    dt = t(n+1)-t(n);
    % Block 0
    v_ADNCYC = V_ADNCYC*EV(n)/(K_EV_AC+EV(n))*ATP_fraction;              % ATP -> cAMP
    v_PDE1   = V_PDE1*m_cAMP(n)/(Km_PDE1_cAMP+m_cAMP(n));            % cAMP -> AMP
    v_NTD7   = V_NTD7*m_AMP(n)/(Km_NTD7_AMP+m_AMP(n));               % AMP -> adenosine
    v_PUNP1  = V_PUNP1*m_adn(n)/(Km_PUNP1_adn+m_adn(n))*Pi_fraction;     % adenosine -> ribose-1-P
    v_PYNP2r = V_PYNP2r*m_r1p(n)/(Km_PYNP2r_r1p+m_r1p(n))*uracil_fraction;   % ribose-1-P -> uridine
    v_r1156 = V_r1156*m_uri(n)/(Km_r1156_uri+m_uri(n))*dUTP_fraction;   % uridine -> UMP

    m_cAMP(n+1) = m_cAMP(n)+dt*(v_ADNCYC-v_PDE1);
    m_AMP(n+1)  = m_AMP(n) +dt*(v_PDE1-v_NTD7);
    m_adn(n+1)  = m_adn(n) +dt*(v_NTD7-v_PUNP1);
    m_r1p(n+1)  = m_r1p(n) +dt*(v_PUNP1-v_PYNP2r);
    m_uri(n+1)  = m_uri(n) +dt*(v_PYNP2r-v_r1156);
    m_in(n+1)   = m_in(n)  +dt*(v_r1156-(k_S+k_F)*m_in(n));

    % ---- Differentiator 1 ----
    m_F(n+1) = m_F(n)+dt*(k_F*m_in(n)-k_Fr*m_F(n));                    % fast delay pool
    m_S(n+1) = m_S(n)+dt*(k_S*m_in(n)-k_Sr*m_S(n));                    % slow delay pool
    P = m_P1(n)+dt*(k_Fr*m_F(n)-k_Fx*m_P1(n));                         % fast rail
    Q = m_d1(n)+dt*(k_Sr*m_S(n)-(k_F_2+k_S_2)*m_d1(n));                % slow rail; removal = load of D2
    D = P-Q;                                                           % canceler, implicit over dt
    qb = 1-dt*k_I*D;  qd = sqrt(qb^2+4*dt*k_I*P);
    if qb > 0
        P = 2*P/(qb+qd);
    else
        P = (qd-qb)/(2*dt*k_I);
    end
    m_P1(n+1) = max(P,0);  m_d1(n+1) = max(P-D,0);

    % ---- Differentiator 2 (fed by the m_d1 it consumes) ----
    m_F2(n+1) = m_F2(n)+dt*(k_F_2*m_d1(n)-k_Fr_2*m_F2(n));             % fast delay pool
    m_S2(n+1) = m_S2(n)+dt*(k_S_2*m_d1(n)-k_Sr_2*m_S2(n));             % slow delay pool
    P = m_d2(n)+dt*(k_Fr_2*m_F2(n)-k_Fx_2*m_d2(n));                    % fast rail = output
    Q = m_N2(n)+dt*(k_Sr_2*m_S2(n)-k_Sx_2*m_N2(n));                    % slow rail
    D = P-Q;                                                           % canceler, implicit over dt
    qb = 1-dt*k_I_2*D;  qd = sqrt(qb^2+4*dt*k_I_2*P);
    if qb > 0
        P = 2*P/(qb+qd);
    else
        P = (qd-qb)/(2*dt*k_I_2);
    end
    m_d2(n+1) = max(P,0);  m_N2(n+1) = max(P-D,0);

    % ---- Counter (activated by m_d2) ----
    gate(n) = m_d2(n)/(K_gate+m_d2(n));
    v_Cp = V_Cp*gate(n);                                               % r_c : -> m_c
    v_Cg = V_Cg*m_c(n)/(KM_Cg_c+m_c(n))*m_I(n)/(KM_Cg_I+m_I(n));       % r_I1: m_c + m_I -> products
    v_Cr = V_Cr*gate(n)*m_I(n)/(KM_Cr+m_I(n));                         % r_I2: m_I -> products
    m_c(n+1) = m_c(n)+dt*(v_Cp-v_Cg);
    m_I(n+1) = m_I(n)+dt*(k_I_supply*(m_I_base-m_I(n))-v_Cr-v_Cg);

    pools = [m_in(n+1),m_F(n+1),m_S(n+1),m_P1(n+1),m_d1(n+1),m_F2(n+1),m_S2(n+1),m_d2(n+1),m_N2(n+1),m_c(n+1),m_I(n+1)];
    assert(all(isfinite(pools)) && all(pools >= 0),'Invalid step at n = %d; reduce dt0.',n);
end
gate(N) = m_d2(N)/(K_gate+m_d2(N));
%%
%[text] ## 7. Diagnostics
% The identity behind the design, computed by plain filtering of m_in:
% m_P1 - m_d1 = w_1*(m_in delayed by tau_F1 - m_in delayed by tau_S1), smoothed with tau_r1.
x_F = m_in;  x_S = m_in;  ideal_1 = zeros(N,1);
for n = 1:N-1
    x_F(n+1) = x_F(n)+dt0*(m_in(n)-x_F(n))/tau_F1;
    x_S(n+1) = x_S(n)+dt0*(m_in(n)-x_S(n))/tau_S1;
    ideal_1(n+1) = ideal_1(n)+dt0*(w_1*(x_F(n)-x_S(n))-ideal_1(n))/tau_r1;
end
diff_1 = m_P1-m_d1;
fprintf('\nD1: m_P1 - m_d1 against the ideal subtraction: largest gap %.3g mM (signal up to %.3g mM)\n', ... %[output:group:21a29b5f] %[output:0cd6e7bb]
    max(abs(diff_1-ideal_1)),max(abs(ideal_1))); %[output:group:21a29b5f] %[output:0cd6e7bb]
fprintf('D1 output m_d1: rest %.3g, peak %.3g at %.3g min, last %.3g mM;  m_P1 peak %.3g mM\n', ... %[output:group:4ce5d30f] %[output:94ccf234]
    m_d1(1),max(m_d1),t(find(m_d1 == max(m_d1),1))/60,m_d1(end),max(m_P1)); %[output:group:4ce5d30f] %[output:94ccf234]
fprintf('D2 output m_d2: rest %.3g, peak %.3g at %.3g min, last %.3g mM;  m_N2 peak %.3g mM\n', ... %[output:group:8173ca3a] %[output:051ca0bc]
    m_d2(1),max(m_d2),t(find(m_d2 == max(m_d2),1))/60,m_d2(end),max(m_N2)); %[output:group:8173ca3a] %[output:051ca0bc]
fprintf('Counter: activation rest %.3g, largest %.3g;  m_c rest %.3g, peak %.3g at %.3g min, last %.3g mM\n', ... %[output:group:61f2b23b] %[output:2ee5745f]
    gate(1),max(gate),m_c(1),max(m_c),t(find(m_c == max(m_c),1))/60,m_c(end)); %[output:group:61f2b23b] %[output:2ee5745f]
fprintf('Largest pool / K_M (first-order kinetics need << 1): m_F %.2g, m_S %.2g, m_F2 %.2g, m_S2 %.2g\n', ... %[output:group:02f0a0fd] %[output:018bbf5e]
    max(m_F)/KM_Fr,max(m_S)/KM_Sr,max(m_F2)/KM_Fr_2,max(m_S2)/KM_Sr_2); %[output:group:02f0a0fd] %[output:018bbf5e]
%%
%[text] ## 8. Figures
% 1. Input.
figure; %[output:505203fe]
plot(t/60,m_in,'LineWidth',2); grid on; %[output:505203fe]
xlabel('Time [min]'); ylabel('UMP: m_{in} [mM]'); set(gca,'FontSize',fontsize+4); %[output:505203fe]

% 2. Differentiator 1: the two delay pools.
figure; %[output:168453bb]
plot(t/60,[m_F/m_F(1),m_S/m_S(1),m_in/m_in(1)],'LineWidth',2); grid on; %[output:168453bb]
xlabel('Time [min]'); ylabel('relative to rest'); xlim([0,min(30,t(end)/60)]); %[output:168453bb]
legend('m_F (fast delay pool)','m_S (slow delay pool)','m_{in}','Location','best'); set(gca,'FontSize',fontsize); %[output:168453bb]

% 3. Differentiator 1: the two rails, and the falling slope of the input.
figure; %[output:264540c6]
yyaxis left;  plot(t/60,[m_d1,m_P1],'LineWidth',2); ylabel('Concentration [mM]'); %[output:264540c6]
yyaxis right; plot(t/60,-gradient(m_in,t),':','LineWidth',1.5); ylabel('-dm_{in}/dt [mM/s]'); %[output:264540c6]
xlabel('Time [min]'); xlim([0,min(150,t(end)/60)]); grid on; %[output:264540c6]
legend('m_{d1} (slow rail, output)','m_{P1} (fast rail)','input falling slope','Location','best'); %[output:264540c6]
set(gca,'FontSize',fontsize); %[output:264540c6]

% 4. Differentiator 2: the two rails, and the slope of m_d1.
figure; %[output:7ccd839c]
yyaxis left;  plot(t/60,[m_d2,m_N2],'LineWidth',2); ylabel('Concentration [mM]'); %[output:7ccd839c]
yyaxis right; plot(t/60,gradient(m_d1,t),':','LineWidth',1.5); ylabel('dm_{d1}/dt [mM/s]'); %[output:7ccd839c]
xlabel('Time [min]'); xlim([0,min(150,t(end)/60)]); grid on; %[output:7ccd839c]
legend('m_{d2} (fast rail, output)','m_{N2} (slow rail)','slope of m_{d1}','Location','best'); %[output:7ccd839c]
set(gca,'FontSize',fontsize); %[output:7ccd839c]

% 5. Check of the identity: difference of the rails against the ideal subtraction.
figure; %[output:5a06b534]
plot(t/60,diff_1,'LineWidth',2); hold on; plot(t/60,ideal_1,'--','LineWidth',1.5); grid on; %[output:5a06b534]
xlabel('Time [min]'); ylabel('[mM]'); xlim([0,min(150,t(end)/60)]); %[output:5a06b534]
legend('m_{P1} - m_{d1}','w_1 (fast-delayed - slow-delayed m_{in})','Location','best'); set(gca,'FontSize',fontsize); %[output:5a06b534]

% 6. Counter.
figure; %[output:7abb19c7]
yyaxis left;  plot(t/60,m_c,'LineWidth',2); ylabel('m_c [mM]'); %[output:7abb19c7]
yyaxis right; plot(t/60,gate,'--','LineWidth',1.5); ylabel('activation by m_{d2}'); ylim([0 1]); %[output:7abb19c7]
xlabel('Time [min]'); xlim([0,min(150,t(end)/60)]); grid on; %[output:7abb19c7]
legend('m_c (counter)','activation of r_c','Location','best'); set(gca,'FontSize',fontsize); %[output:7abb19c7]
